-- OGEIDA CRM — Migration 004
-- Apply AFTER migrations 001, 002, and 003 on Development/Staging only.
-- Goals:
--   1) Only Admin can assign/revoke Team Leader role and employee visibility scope.
--   2) Users cannot promote themselves or alter teamMembers/role via direct table writes.
--   3) Employees can append multiple feedback records to their own Leads.
--   4) Feedback timestamp is generated by PostgreSQL at insert time (epoch ms in data.at).

begin;

-- Guard member profile writes. Non-admin users may submit/update their own display name,
-- but protected access fields are always stripped on insert and restored from OLD on update.
create or replace function public.guard_member_access_fields()
returns trigger
language plpgsql
security invoker
set search_path = public
as $$
declare
  protected_keys text[] := array[
    'role','teamMembers','roleUpdatedAt','roleUpdatedBy',
    'permissions','is_admin','approved','active','is_active','teams'
  ];
begin
  if new.collection <> 'members' then
    return new;
  end if;

  if public.is_admin() then
    return new;
  end if;

  if auth.uid() is null or new.id <> auth.uid()::text then
    raise exception 'members_self_record_only' using errcode = '42501';
  end if;

  if tg_op = 'INSERT' then
    new.data := new.data - protected_keys;
  elsif tg_op = 'UPDATE' then
    new.data := (new.data - protected_keys) || (old.data - (old.data - protected_keys));
  end if;

  return new;
end;
$$;

drop trigger if exists trg_guard_member_access_fields on public.docs;
create trigger trg_guard_member_access_fields
before insert or update on public.docs
for each row execute function public.guard_member_access_fields();

-- Single trusted entry point for assigning a Team Leader and the exact employees they may view.
-- SECURITY DEFINER is safe here because the function checks is_admin() itself and validates all IDs.
create or replace function public.admin_set_team_access(
  target_user text,
  new_role text,
  allowed_members jsonb default '[]'::jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  clean_members jsonb;
  member_count integer;
  valid_count integer;
  old_data jsonb;
begin
  if not public.is_admin() then
    raise exception 'admin_only_team_access' using errcode = '42501';
  end if;

  if new_role not in ('sales','team_leader') then
    raise exception 'invalid_role' using errcode = '22023';
  end if;

  if allowed_members is null or jsonb_typeof(allowed_members) <> 'array' then
    raise exception 'allowed_members_must_be_array' using errcode = '22023';
  end if;

  select coalesce(data,'{}'::jsonb) into old_data
  from public.docs where collection='members' and id=target_user;

  if old_data is null then
    raise exception 'target_member_not_found' using errcode = 'P0002';
  end if;

  if not exists (select 1 from public.profiles p where p.id::text=target_user and p.approved=true and p.is_admin=false) then
    raise exception 'target_must_be_approved_non_admin' using errcode = '22023';
  end if;

  if new_role = 'team_leader' then
    clean_members := (
      select coalesce(jsonb_agg(distinct to_jsonb(x)), '[]'::jsonb)
      from jsonb_array_elements_text(allowed_members) as t(x)
      where x <> target_user
    );
  else
    clean_members := '[]'::jsonb;
  end if;

  select count(*) into member_count
  from (select distinct value as id from jsonb_array_elements_text(clean_members)) q;

  select count(*) into valid_count
  from (
    select distinct x as id
    from jsonb_array_elements_text(clean_members) as t(x)
    join public.profiles p on p.id::text=x and p.approved=true and p.is_admin=false
    join public.docs m on m.collection='members' and m.id=x
  ) q;

  if member_count <> valid_count then
    raise exception 'team_scope_contains_unapproved_or_missing_user' using errcode = '22023';
  end if;

  update public.docs
  set data = jsonb_set(
      jsonb_set(
        jsonb_set(coalesce(data,'{}'::jsonb), '{role}', to_jsonb(new_role), true),
        '{teamMembers}', clean_members, true
      ),
      '{roleUpdatedAt}', to_jsonb((extract(epoch from clock_timestamp()) * 1000)::bigint), true
    ) || jsonb_build_object('roleUpdatedBy', auth.uid()::text),
      updated_at = now()
  where collection='members' and id=target_user;

  return jsonb_build_object('user',target_user,'role',new_role,'teamMembers',clean_members);
end;
$$;

revoke all on function public.admin_set_team_access(text,text,jsonb) from public;
grant execute on function public.admin_set_team_access(text,text,jsonb) to authenticated;

-- Authoritative feedback timestamp and ownership validation.
-- Each INSERT is a separate feedback event; no overwrite of earlier feedback is performed.
create or replace function public.stamp_and_guard_feedback_insert()
returns trigger
language plpgsql
security invoker
set search_path = public
as $$
declare
  lead_owner text;
  inserted_ms bigint;
begin
  if new.collection <> 'feedback' then
    return new;
  end if;

  if not public.is_approved() then
    raise exception 'not_approved' using errcode = '42501';
  end if;

  if not public.is_admin() then
    if auth.uid() is null then
      raise exception 'authentication_required' using errcode = '42501';
    end if;
    if new.data->>'by' is distinct from auth.uid()::text then
      raise exception 'feedback_author_mismatch' using errcode = '42501';
    end if;
  end if;

  select data->>'owner' into lead_owner
  from public.docs
  where collection='leads' and id=new.data->>'lead';

  if lead_owner is null then
    raise exception 'feedback_lead_not_found' using errcode = 'P0002';
  end if;

  if not public.is_admin() and lead_owner <> auth.uid()::text then
    raise exception 'feedback_own_lead_only' using errcode = '42501';
  end if;

  inserted_ms := (extract(epoch from clock_timestamp()) * 1000)::bigint;
  new.data := jsonb_set(coalesce(new.data,'{}'::jsonb), '{at}', to_jsonb(inserted_ms), true);
  new.data := jsonb_set(new.data, '{confirmed}', 'true'::jsonb, true);
  return new;
end;
$$;

drop trigger if exists trg_stamp_and_guard_feedback_insert on public.docs;
create trigger trg_stamp_and_guard_feedback_insert
before insert on public.docs
for each row execute function public.stamp_and_guard_feedback_insert();

commit;
